<?php
if(!defined('ABSPATH'))exit;
function dgs_record_registration_year($m){if(!empty($m['registration_year']))return $m['registration_year'];if(!empty($m['updated_at'])){$p=explode('-',substr($m['updated_at'],0,10));if(count($p)===3){$j=dgs_jalali_parts((int)$p[0],(int)$p[1],(int)$p[2]);$y=$j[0]-($j[1]<7?1:0);return $y.'-'.($y+1);}}return dgs_edu_current_year();}
function dgs_record_registration($id,$year,$m){$v=get_user_meta($id,'_dgs_registration_'.$year,true);if(metadata_exists('user',$id,'_dgs_registration_'.$year))return $v;return dgs_record_registration_year($m)===$year?($m['registration']??''):'';}
function dgs_school_year_box($year){return '<section class="dsp-card dsp-year-box"><div><h3>'.dgs_school_icon('calendar').' مدیریت سال تحصیلی</h3><p>سال فعال مدرسه: <strong>'.esc_html(dgs_fa_digits(dgs_edu_current_year())).'</strong> · سال در حال مشاهده: <strong>'.esc_html(dgs_fa_digits($year)).'</strong></p></div>'.dgs_edu_form_start('year','education',$year).'<label>سال تحصیلی فعال مدرسه<input name="year" value="'.esc_attr(dgs_edu_current_year()).'" dir="ltr" pattern="14[0-9]{2}-14[0-9]{2}" required></label><button class="dg-btn">ذخیره سال فعال</button></form><details><summary>با شروع سال جدید چه کنیم؟</summary><p>۱. سال جدید مانند 1406-1407 را فعال کنید. ۲. در تب کلاس‌ها، کلاس‌های همین سال را تعریف کنید. ۳. دانش‌آموزان موجود را با فرم انتساب یا اکسل دارای همان کد ملی و شناسه کلاس جدید، در سال جدید ثبت کنید. حساب و رمز قبلی حفظ می‌شود؛ پایه خودکار ارتقا پیدا نمی‌کند. ۴. دبیر، برنامه و شهریه سال جدید را جدا تعیین کنید.</p><p>نمره، حضور و غیاب، انضباط، کلاس و حساب مالی سال‌های قبل حذف نمی‌شوند. با فیلتر «سال تحصیلی» بالای فهرست، سوابق سال گذشته را ببینید. اطلاعات هویتی و مدارک متعلق به حساب دانش‌آموزند و مشترک می‌مانند؛ وضعیت ثبت‌نام برای هر سال جدا نگهداری می‌شود. فعال‌کردن سال، داده‌ها را کپی یا حساب‌ها را تسویه نمی‌کند.</p></details><form method="get" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="education"><label>مشاهده سوابق سال تحصیلی<input name="dg_year" value="'.esc_attr($year).'" dir="ltr" pattern="14[0-9]{2}-14[0-9]{2}" required></label><button class="dg-btn dg-btn-outline">مشاهده سوابق</button></form></section>';}
function dgs_admission_page($year){
 if(!current_user_can('dgs_manage_education'))return '';$classes=dgs_edu_class_options(dgs_edu_classes($year));$out='<div class="dsp-school dsp-admission">'.dgs_school_title('افزودن دانش‌آموز و تشکیل پرونده','اطلاعات حساب، پرونده و ثبت‌نام را یک‌جا وارد کنید. ایمیل لازم نیست.').'<a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_edu_url('education',$year)).'">← بازگشت به فهرست دانش‌آموزان</a>'.dgs_school_form('student_create',$year).'<section class="dsp-card"><h3>حساب و ثبت‌نام · سال '.esc_html(dgs_fa_digits($year)).'</h3><div class="dge-grid"><label>نام و نام خانوادگی *<input name="name" maxlength="100" required></label><label>کد ملی *<input name="national_id" minlength="10" maxlength="10" inputmode="numeric" required dir="ltr"></label><label>موبایل دانش‌آموز *<input name="phone" inputmode="tel" required dir="ltr"></label><label>موبایل پدر / ولی<input name="guardian_phone" inputmode="tel" dir="ltr"></label><label>کد دانش‌آموزی<input name="student_code" maxlength="30"></label>'.dgs_edu_select('class_id','کلاس این سال (اختیاری)',$classes,0,false).'</div><p class="dsp-footnote">نام کاربری و رمز اولیه کد ملی است؛ حساب دانش‌آموز در سال‌های بعد دوباره ساخته نمی‌شود.</p></section>';
 $groups=array('اطلاعات هویتی'=>array('father','birth','gender','birthplace','nationality'),'اطلاعات تماس'=>array('mother_phone','home_phone','address'),'اطلاعات ولی (سرپرست قانونی)'=>array('guardian_name','relation','guardian_national','occupation','workplace'),'پذیرش و پرونده'=>array('entry_year','admission','registration'));$labels=dgs_record_fields();foreach($groups as $title=>$fields){$out.='<section class="dsp-card"><h3>'.esc_html($title).'</h3><div class="dge-grid">';foreach($fields as $k){$out.='<label>'.esc_html($labels[$k]);if($k==='address')$out.='<textarea name="address" maxlength="500" rows="3"></textarea>';else $out.='<input name="'.esc_attr($k).'" maxlength="120" '.($k==='birth'?'placeholder="1387-05-21" dir="ltr"':'').'>'; $out.='</label>';}$out.='</div></section>';}
 return $out.'<div class="dsp-actions"><button class="dg-btn">✓ ثبت دانش‌آموز و پرونده</button><a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_edu_url('education',$year)).'">انصراف</a></div></form></div>';
}

function dgs_admission_excel_help($classes){$out='<details class="dsp-excel-help"><summary>راهنمای ستون‌های پرونده و شناسه کلاس‌ها</summary><p>شش ستون اول: national_id کد ملی، full_name نام کامل، phone موبایل دانش‌آموز، guardian_phone موبایل ولی، student_code کد دانش‌آموز، class_id شناسه کلاس همین سال.</p><ul>';foreach(dgs_record_fields() as $k=>$label)$out.='<li><code>'.esc_html($k).'</code> — '.esc_html($label).'</li>';$out.='</ul><p>کد ملی، نام کامل و موبایل دانش‌آموز اجباری‌اند؛ سایر اطلاعات اختیاری. تاریخ تولد مانند 1387-05-21 است. برای سال جدید، کد ملی قبلی و class_id کلاس جدید را وارد کنید؛ اطلاعات هویتی و رمز حساب موجود بازنویسی نمی‌شود.</p><ul>';foreach($classes as $c)$out.='<li>class_id: <strong>'.(int)$c->id.'</strong> — '.esc_html(dgs_edu_grade_label($c->grade).' '.$c->title.' · '.(dgs_edu_fields()[$c->field]??'')).'</li>';return $out.'</ul></details>';}
